import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { isDocsPage, localeOf, markdownUrl } from './docs.ts';
import { t, type Key } from './i18n.ts';

type SidebarEntry = { type: 'link' } | { type: 'group'; label: string; entries: SidebarEntry[] };

// Starlight labels an autogenerated subfolder with its folder name; these get their translated label.
const folderLabels = new Set(['guides', 'sdk', 'ui', 'cli']);

function relabel(entries: SidebarEntry[], locale: 'en' | 'de'): void {
  for (const entry of entries) {
    if (entry.type !== 'group') {
      continue;
    }
    if (folderLabels.has(entry.label)) {
      entry.label = t(locale, `sidebar.folder.${entry.label}` as Key);
    }
    relabel(entry.entries, locale);
  }
}

// Every docs page points to its Markdown twin, and a page that is not checked against the code says so in a banner.
export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  const { entry } = route;
  relabel(route.sidebar as SidebarEntry[], route.locale === 'de' ? 'de' : 'en');
  if (!isDocsPage(entry.id) || entry.id.endsWith('404')) {
    return;
  }
  route.head.push({
    tag: 'link',
    attrs: {
      rel: 'alternate',
      type: 'text/markdown',
      href: markdownUrl(entry.id),
      title: 'Markdown',
    },
  });
  if (entry.data.status !== 'ready' && !entry.data.banner) {
    entry.data.banner = { content: t(localeOf(entry.id), `status.${entry.data.status}`) };
  }
});
